# ================= fishing: 行属性（前端筛选器用） =================
# 原则：属性【全部机械推导自已有英文单元格】，不新增任何事实。
# 推导一次后按索引复制给每个语言——属性是语义标签，与语言无关（翻译会替换行文本但顺序不变）。
# ⚠️ 天气/需求扫描必须【排除鱼名列】：Rainbow Trout 的 "Rain" 不是天气条件（踩过这个坑）。
_FISH_LOC = {
  "pond":    ["East Town Pond","Mountain Ponds","Deep Woods","Lily Pads","Hidden Cliff","Ridge Valley","ponds"],
  "sea":     ["Hovercraft Dock","Town Dock Center","Under Pier"],
  "shallow": ["Wetland shallows","Farm","Back Hills","West Grove","Valley Outpost","Mining Ruins","Junk Mountain"],
  "cave":    ["Moss Cave"],
}
_FISH_PERIOD = {0: "allyear", 1: "rainy", 2: "dry", 3: "single"}

def _fish_attrs(table_index, row, columns):
    cell = {c: row[i] for i, c in enumerate(columns) if i < len(row)}
    rest = " ".join(row[1:])                      # 排除鱼名列
    how = "breed" if re.search(r"\bBreed\b", rest) else "catch"
    t_ = cell.get("Time", "Any")
    if re.search(r"\bRain\b|\bThunderstorm\b|Acid Rain", rest): weather = "rain"
    elif re.search(r"\bScorching\b", rest):                        weather = "sun"
    else:                                                            weather = "any"
    req = [k for k, kw in (("watercore","Water Core"),("bamboo","Bamboo"),("rockcore","Rock Core")) if kw in rest]
    loc = [k for k, vs in _FISH_LOC.items() if any(v.lower() in rest.lower() for v in vs)]
    return {
      "period":  "breed" if how == "breed" else _FISH_PERIOD.get(table_index, "allyear"),
      "how":     how,
      "time":    "night" if "18:00–2" in t_ else ("day" if "6:00–18" in t_ else "any"),
      "weather": weather,
      "req":     " ".join(req) or "none",
      "loc":     " ".join(loc) or "none",
    }

_fp = next((x for x in d["pages"] if x["slug"] == "fishing"), None)
if _fp:
    _tables_en = [s for s in _fp["sections"] if s.get("type") == "table"]
    _attrs_by_table = [
      [_fish_attrs(i, r, s.get("columns", [])) for r in s.get("rows", [])]
      for i, s in enumerate(_tables_en)
    ]
    def _attach(sections):
        ti = 0
        for s in sections:
            if s.get("type") != "table": continue
            if ti < len(_attrs_by_table) and len(s.get("rows", [])) == len(_attrs_by_table[ti]):
                s["rowAttrs"] = _attrs_by_table[ti]
            ti += 1
    _attach(_fp["sections"])
    for _lg, _t in (_fp.get("i18n") or {}).items():
        _attach(_t.get("sections", []))
    # The former filter advertised removed recipe rows and a stale total.
    # Replace it with a source-boundary note so ad placement and reading order
    # remain stable without preserving an empty or misleading control.
    _fish_scope = {
        "en": ("Catch chart scope", "These tables list currently documented catches and requirements. Recheck the in-game catalog after patches."),
        "zh-CN": ("渔获表范围", "这些表格列出当前有记录的渔获与条件；补丁更新后请在游戏内图鉴中复核。"),
        "zh-TW": ("漁獲表範圍", "這些表格列出目前有記錄的漁獲與條件；更新後請在遊戲內圖鑑中複核。"),
        "ja": ("釣果表の範囲", "表は現在記録されている釣果と条件を掲載しています。更新後はゲーム内図鑑で再確認してください。"),
        "ko": ("어획표 범위", "이 표는 현재 기록된 어획과 조건을 정리합니다. 패치 후에는 게임 내 도감에서 다시 확인하세요."),
        "es": ("Alcance de las tablas", "Estas tablas recogen capturas y requisitos documentados. Vuelve a comprobar el catálogo del juego tras los parches."),
    }
    _fp["sections"] = [s for s in _fp["sections"] if s.get("type") != "fishfilter" and s.get("tag") != "CATCH-SCOPE"]
    _fp["sections"].insert(0, {"type":"note", "tag":"CATCH-SCOPE", "heading":_fish_scope["en"][0], "body":_fish_scope["en"][1]})
    for _lg, _t in (_fp.get("i18n") or {}).items():
        _t["sections"] = [s for s in _t.get("sections", []) if s.get("type") != "fishfilter" and s.get("tag") != "CATCH-SCOPE"]
        _heading, _body = _fish_scope[_lg]
        _t["sections"].insert(0, {"type":"note", "tag":"CATCH-SCOPE", "heading":_heading, "body":_body})
    print("fishing rowAttrs:", sum(len(a) for a in _attrs_by_table), "行 ×", 1 + len(_fp.get("i18n") or {}), "语言")

# ================= gene-system: 行属性（前端筛选器用） =================
# 原则：属性全部机械推导自已有英文单元格（Effect/Best use），不新增任何事实；
# 推导一次后按索引复制给每个语言（翻译会替换行文本但顺序不变，行数必须相等才挂）。
# ⚠️ 排除名称列（Mutation）：名称里的词不做归类依据。
# 第 7 行「+ ~14 more」是待验证占位 → unlisted（筛选器提供 unlisted 选项，可单独筛出）。
def _gene_attrs(row, columns):
    rest = " ".join(row[1:])   # Effect + Best use（排除名称列）
    if re.search(r"Auto-waters|auto-water|waters nearby|waters surrounding", rest, re.I):
        effect = "water"
    elif re.search(r"drop fruit automatically|automatically", rest, re.I):
        effect = "harvest"
    elif re.search(r"Extra drops|\+1 fruit|Increases drop", rest, re.I):
        effect = "yield"
    elif re.search(r"drop seeds|self-sustaining", rest, re.I):
        effect = "seeds"
    elif re.search(r"off-season|Survives", rest, re.I):
        effect = "survival"
    else:
        effect = "unlisted"
    return {"effect": effect}

_gp = next((x for x in d["pages"] if x["slug"] == "gene-system"), None)
if _gp:
    _tables_en = [s for s in _gp["sections"] if s.get("type") == "table"]
    _gene_attrs_by_table = [
      [_gene_attrs(r, s.get("columns", [])) for r in s.get("rows", [])]
      for s in _tables_en
    ]
    def _attach_gene(sections):
        ti = 0
        for s in sections:
            if s.get("type") != "table": continue
            if ti < len(_gene_attrs_by_table) and len(s.get("rows", [])) == len(_gene_attrs_by_table[ti]):
                s["rowAttrs"] = _gene_attrs_by_table[ti]
            ti += 1
    _attach_gene(_gp["sections"])
    for _lg, _t in (_gp.get("i18n") or {}).items():
        _attach_gene(_t.get("sections", []))
    # 首节插入筛选器（幂等）
    _gp["sections"] = [s for s in _gp["sections"] if s.get("type") != "genefilter"]
    _gp["sections"].insert(0, {"type": "genefilter"})
    for _lg, _t in (_gp.get("i18n") or {}).items():
        _t["sections"] = [s for s in _t.get("sections", []) if s.get("type") != "genefilter"]
        _t["sections"].insert(0, {"type": "genefilter"})
    print("gene rowAttrs:", sum(len(a) for a in _gene_attrs_by_table), "行 ×", 1 + len(_gp.get("i18n") or {}), "语言")


