# The cited first-party sources support farming automation and drone stations,
# but they do not assign that system a numbered or phased structure. Keep the
# authoring source clean and fail the build if stale attribution returns; this
# validator reports debt instead of silently rewriting published content.
_unsupported_automation_phase_tokens = (
    "two-" + "stage", "two " + "phase", "两" + "阶段", "兩" + "階段",
    "二" + "段階", "2" + "단계", "dos " + "etapas", "dos " + "fases",
)
def _reject_unsupported_automation_phases(value, trail="site"):
    if isinstance(value, dict):
        for key, child in value.items():
            _reject_unsupported_automation_phases(child, f"{trail}.{key}")
    elif isinstance(value, list):
        for index, child in enumerate(value):
            _reject_unsupported_automation_phases(child, f"{trail}[{index}]")
    elif isinstance(value, str):
        folded = value.casefold()
        for token in _unsupported_automation_phase_tokens:
            if token.casefold() in folded:
                raise ValueError(f"unsupported automation phase attribution at {trail}")

_reject_unsupported_automation_phases(d)

